import {STRINGS,handPose,mouthO,noteInfo} from './gestures.js';
import {PRESETS,PRESET_NAMES,OPEN_MIDI,hz,nameOf,stringPosition,staffY,Synth,weights,cyclePosition,bowBrightness,smoothBrightness,bowPartials} from './music.js?v=5';
const $=id=>document.getElementById(id),synth=new Synth();
let mode='strings',string=2,fingers=0,touch=false,mouth=false,preview=false,selected=new Map(),history=[],lastSignature='',lastSound=[],preset='warm';
let stream,worker,running=false,starting=false,busy=false,raf,generation=0,lastFrame=0,lastResult=0,rightSeen=0,gate=false,mutedUntilAbsent=false,thumbStart=0,thumbDir=0,thumbLocked=false,candidate=-1,candidateSince=0,loadTimer;
let brightness=.5,lastBowTime=0;
const boardButtons=[],sliders=[];
const harmonic=()=>mode==='camera'?(touch||mouth):(lastSound[0]?.harmonic??false);
function currentNotes(){const h=harmonic();if(mode==='strings')return [...selected].map(([s,n])=>({id:'string'+s,midi:OPEN_MIDI[s]+n.position+(n.harmonic?12:0),harmonic:n.harmonic}));if(preview||(running&&gate&&!mutedUntilAbsent))return [{id:'camera',midi:noteInfo(string,fingers,h).midi,harmonic:h,partials:running?bowPartials(brightness):null}];return [];}
function refresh(){const notes=currentNotes();synth.sync(notes);const sig=notes.map(n=>n.id+':'+n.midi+':'+n.harmonic).join('|');if(sig!==lastSignature){if(notes.length&&synth.context?.state==='running'){history.push(notes.map(n=>({...n})));history=history.slice(-16);drawStaff();}lastSignature=sig;}lastSound=notes;render();}
async function sound(){try{await synth.ready();refresh();}catch(e){$('technique').textContent='Sound unavailable';$('status').textContent='Could not start audio: '+e.message;}}
for(let i=0;i<4;i++){const b=document.createElement('button');b.textContent=STRINGS[i].name;b.setAttribute('aria-label',STRINGS[i].name+' string');b.onclick=()=>{string=i;refresh();};$('strings').append(b);}
for(let i=0;i<5;i++){const b=document.createElement('button');b.textContent=i;b.setAttribute('aria-label',i+' fingers');b.onclick=()=>{fingers=i;refresh();};$('fingers').append(b);}
// Circles use the equal-tempered stopped-string distance from the nut.
for(let s=3;s>=0;s--){const row=document.createElement('div');row.className='string-row';row.innerHTML='<span class="string-label">'+STRINGS[s].name+'</span><div class="string-line"></div>';
 for(let n=0;n<=12;n++){const b=document.createElement('button');b.className='position';b.style.setProperty('--position',(4+stringPosition(n)*90)+'%');b.innerHTML=(n===0?'○':n)+'<span class="position-name">'+nameOf(OPEN_MIDI[s]+n)+'</span>';b.setAttribute('aria-label',STRINGS[s].name+' string '+nameOf(OPEN_MIDI[s]+n));b.setAttribute('aria-pressed','false');b.title=nameOf(OPEN_MIDI[s]+n)+(n?' · '+n+' semitones':' · open string');b.onclick=()=>{const next=cyclePosition(selected.get(s),n);if(next)selected.set(s,next);else selected.delete(s);sound();};row.append(b);boardButtons.push({b,s,n});}
 $('fingerboard').append(row);
}
for(let i=0;i<8;i++){const label=document.createElement('label');label.className='partial';label.innerHTML='<div class="partial-visual" aria-hidden="true"><div class="partial-fill"></div></div><strong>'+(i===0?'Fundamental':'Harmonic '+(i+1))+'</strong><input type="range" min="0" max="100" step="1" value="'+Math.round(synth.partials[i]*100)+'" aria-label="'+(i===0?'Fundamental amplitude':'Harmonic '+(i+1)+' amplitude')+'"><output></output><span class="hz"></span>';
 const input=label.querySelector('input');input.oninput=()=>{const p=[...synth.partials];p[i]=Number(input.value)/100;synth.setPartials(p);preset='custom';renderMixer();};sliders.push({label,input});$('partials').append(label);
}
for(const b of document.querySelectorAll('[data-preset]'))b.onclick=()=>{preset=b.dataset.preset;synth.setPartials(PRESETS[preset]);renderMixer();};
function renderMixer(){const ref=lastSound[0]?.midi??noteInfo(string,fingers,harmonic()).midi,base=hz(ref),bowActive=mode==='camera'&&running,displayPartials=bowActive?bowPartials(brightness):synth.partials,actual=weights(displayPartials,harmonic()),max=Math.max(.001,...actual);sliders.forEach(({label,input},i)=>{input.disabled=bowActive;input.value=Math.round(displayPartials[i]*100);label.querySelector('output').textContent=Math.round(displayPartials[i]*100)+'%';label.querySelector('.partial-fill').style.height=(actual[i]/max*100)+'%';label.querySelector('.hz').textContent=Math.round(base*(i+1))+' Hz';});document.querySelectorAll('[data-preset]').forEach(b=>{b.disabled=bowActive;b.setAttribute('aria-pressed',String(!bowActive&&b.dataset.preset===preset));});$('timbreName').textContent=(bowActive?'Bow position · '+Math.round(brightness*100)+'% brightness':PRESET_NAMES[preset]||'Your custom mixture')+(harmonic()?' · harmonic touch':'');$('spectrumCaption').textContent=(lastSound.length>1?'First chord voice: ':'Harmonic spacing: ')+Math.round(base)+' Hz · bars show relative output';$('mixerTip').textContent=bowActive?'Hand height controls these amplitudes live: top = fingerboard / soft; bottom = bridge / bright. The selected fundamental stays fixed. Stop the camera to edit presets and sliders.':harmonic()?'The displayed voice is a harmonic: it sounds one octave higher with softer upper partials. Normal notes keep their own pitch and full mixer range.':synth.partials.every(x=>x===0)?'All amplitudes are zero: the instrument is silent. Raise a slider or choose a preset.':'Try holding A, then switch Pure → Electric. The pitch stays A while the timbre changes.';}
function render(){const bowActive=mode==='camera'&&running;$('bowReadout').textContent=bowActive?(brightness<.3?'Over fingerboard · soft / flute-like':brightness>.7?'Near bridge · bright / rich':'Between fingerboard & bridge'):'Point your right index to play. Top = soft; bottom = bright.';$('bowAmount').textContent=Math.round(brightness*100)+'% upper-harmonic blend';$('bowIndicator').style.top=(brightness*100)+'%';const h=harmonic(),midi=lastSound[0]?.midi??noteInfo(string,fingers,h).midi,name=nameOf(midi),octave=name.slice(-1);$('note').innerHTML=name.slice(0,-1)+'<span>'+octave+'</span>';$('frequency').textContent=lastSound.length>1?lastSound.length+' notes together':Math.round(hz(midi))+' Hz · '+(lastSound.length?'playing':'selected');$('harmonicBadge').textContent=lastSound.some(n=>n.harmonic)&&lastSound.some(n=>!n.harmonic)?'MIXED':h?'HARMONIC':'NORMAL';$('harmonicBadge').classList.toggle('on',h);const allH=selected.size>0&&[...selected.values()].every(n=>n.harmonic);$('harmonic').disabled=mode==='strings'&&!selected.size;$('harmonic').textContent=mode==='strings'?(allH?'● Make all normal':'◇ Make all harmonic'):'◇ Harmonic touch: '+(touch?'on':mouth?'mouth':'off');$('harmonic').setAttribute('aria-pressed',String(mode==='strings'?allH:touch));[...$('strings').children].forEach((b,i)=>{b.classList.toggle('active',i===string);b.setAttribute('aria-pressed',String(i===string));});[...$('fingers').children].forEach((b,i)=>{b.classList.toggle('active',i===fingers);b.setAttribute('aria-pressed',String(i===fingers));});$('fingerCount').textContent=fingers+' / 4';boardButtons.forEach(({b,s,n})=>{const value=selected.get(s),active=value?.position===n,isH=active&&value.harmonic;b.classList.toggle('active',active);b.classList.toggle('touch-harmonic',isH);b.setAttribute('aria-pressed',String(active));b.dataset.state=active?(isH?'harmonic':'normal'):'off';b.setAttribute('aria-description',active?(isH?'Harmonic playing. Click to turn off.':'Normal note playing. Click for harmonic.'):'Off. Click to play a normal note.');});$('chordNames').textContent=lastSound.map(n=>nameOf(n.midi)).join(' + ')||'No notes selected';$('meter').style.width=lastSound.length?'100%':'0';$('technique').textContent=mutedUntilAbsent?'MUTED · RELAX INDEX TO RESET':lastSound.length?(mode==='strings'?'STRINGS · ':'CAMERA · ')+lastSound.length+' VOICE'+(lastSound.length>1?'S':''):'READY TO PLAY';$('preview').setAttribute('aria-pressed',String(preview));renderMixer();}
function drawStaff(){let svg='<svg viewBox="0 0 1000 210" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">';for(let y=85;y<=125;y+=10)svg+='<line x1="20" x2="980" y1="'+y+'" y2="'+y+'" stroke="#b9c2af"/>';svg+='<text x="24" y="125" font-size="55" fill="#718069">𝄞</text>';for(let i=0;i<=4;i++)svg+='<line x1="'+(82+i*224)+'" x2="'+(82+i*224)+'" y1="85" y2="125" stroke="#b9c2af"/>';
 history.forEach((event,i)=>{const x=108+i*55;const drawn=new Set();for(const n of event){if(drawn.has(n.midi))continue;drawn.add(n.midi);const y=staffY(n.midi);if(y>=135)for(let l=135;l<=y;l+=10)svg+='<line x1="'+(x-12)+'" x2="'+(x+12)+'" y1="'+l+'" y2="'+l+'" stroke="#87967d"/>';if(y<=75)for(let l=75;l>=y;l-=10)svg+='<line x1="'+(x-12)+'" x2="'+(x+12)+'" y1="'+l+'" y2="'+l+'" stroke="#87967d"/>';svg+='<ellipse cx="'+x+'" cy="'+y+'" rx="8" ry="5.5" fill="'+(n.harmonic?'#47694b33':'#47694b')+'" stroke="#47694b" stroke-width="1.5"/>';if(nameOf(n.midi).includes('♯'))svg+='<text x="'+(x-22)+'" y="'+(y+4)+'" font-size="13" fill="#47694b">♯</text>';}
 svg+='<text x="'+x+'" y="183" text-anchor="middle" font-family="sans-serif" font-size="9" fill="#747a72">'+(event.length>1?'chord':nameOf(event[0].midi))+'</text>';});if(!history.length)svg+='<text x="500" y="160" text-anchor="middle" font-family="sans-serif" font-size="12" fill="#747a72">Your next note starts here.</text>';svg+='</svg>';$('staff').innerHTML=svg;$('staff').scrollLeft=$('staff').scrollWidth;$('staff').setAttribute('aria-label',history.length?'Recent played notes: '+history.map(e=>e.map(n=>nameOf(n.midi)+(n.harmonic?' harmonic':'')).join(' and ')).join(', '):'Musical sketch, no notes played yet');$('scoreStatus').textContent=history.length?history.length+' musical event'+(history.length>1?'s':'')+' in your sketch.':'Play a note to begin.';}
$('clearScore').onclick=()=>{history=[];drawStaff();};$('volume').oninput=()=>synth.setVolume(+$('volume').value/100);$('harmonic').onclick=()=>{if(mode==='strings'){const makeH=![...selected.values()].every(n=>n.harmonic);for(const [s,n] of selected)selected.set(s,{...n,harmonic:makeH});}else touch=!touch;refresh();};
function silence(){preview=false;selected.clear();if(running)mutedUntilAbsent=true;gate=false;synth.silence();lastSignature='';lastSound=[];render();}
$('silence').onclick=silence;
function setMode(next){if(next===mode)return;stopCamera();silence();mode=next;mouth=false;$('cameraPanel').hidden=next!=='camera';$('stringsPanel').hidden=next!=='strings';$('cameraControls').hidden=next!=='camera';$('chordInfo').hidden=next!=='strings';$('preview').hidden=next!=='camera';$('cameraMode').setAttribute('aria-pressed',String(next==='camera'));$('stringsMode').setAttribute('aria-pressed',String(next==='strings'));$('modeHint').textContent=next==='camera'?'Point right index to play. Hand high = soft; hand low = bright.':'Click a circle: normal → harmonic → off. Play up to four strings.';refresh();}
$('cameraMode').onclick=()=>setMode('camera');$('stringsMode').onclick=()=>setMode('strings');$('help').onclick=()=>$('guide').scrollIntoView({behavior:'smooth'});
$('preview').onpointerdown=e=>{e.currentTarget.setPointerCapture(e.pointerId);preview=true;sound();};function releasePreview(){preview=false;refresh();}for(const name of ['pointerup','pointercancel','lostpointercapture'])$('preview').addEventListener(name,releasePreview);$('preview').addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();if(!e.repeat){preview=true;sound();}}});$('preview').addEventListener('keyup',e=>{if(e.key===' '||e.key==='Enter')releasePreview();});
function track(id,found){$(id).classList.toggle('found',found);$(id).textContent=(found?'● ':'○ ')+({leftTrack:'Left hand',rightTrack:'Right hand',faceTrack:'Face'}[id]);}
function process(data){lastResult=performance.now();let left,right;for(const p of data.hands){const isLeft=$('swap').checked?p[0].x<.5:p[0].x>=.5;if(isLeft)left=p;else right=p;}track('leftTrack',!!left);track('rightTrack',!!right);track('faceTrack',!!data.face.length);mouth=mouthO(data.face,mouth);const t=data.time;
 if(left){const pose=handPose(left);if(pose.thumb){if(thumbDir!==pose.thumb){thumbDir=pose.thumb;thumbStart=t;}if(!thumbLocked&&t-thumbStart>500){string=Math.max(0,Math.min(3,string+pose.thumb));thumbLocked=true;}}else{thumbDir=0;thumbStart=0;thumbLocked=false;if(candidate!==pose.count){candidate=pose.count;candidateSince=t;}if(t-candidateSince>110)fingers=candidate;}}else{thumbDir=0;candidate=-1;}
 const pointing=!!right&&handPose(right).point;if(pointing){const target=bowBrightness(right[9].y);brightness=lastBowTime?smoothBrightness(brightness,target,(t-lastBowTime)/1000):target;lastBowTime=t;rightSeen=t;}else if(t-rightSeen>180){mutedUntilAbsent=false;lastBowTime=0;}gate=pointing||(rightSeen>0&&t-rightSeen<180);refresh();drawHands(data.hands,data.face);$('status').textContent=mutedUntilAbsent?'Muted. Relax your pointing finger to reset.':thumbDir?(thumbLocked?'String selected. Return to fingering.':'Hold thumb to change string…'):!pointing?'Point your right index, with other fingers tucked, to play.':!left?'Playing the last selected note. Show left fingers to change it.':'Pointing: playing · Hand high = soft / low = bright · O-mouth = octave harmonic';}
const connections=[[0,1],[1,2],[2,3],[3,4],[0,5],[5,6],[6,7],[7,8],[5,9],[9,10],[10,11],[11,12],[9,13],[13,14],[14,15],[15,16],[13,17],[0,17],[17,18],[18,19],[19,20]];
function drawHands(hands,face){const c=$('overlay'),v=$('video');if(c.width!==v.videoWidth){c.width=v.videoWidth;c.height=v.videoHeight;}const g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);g.lineWidth=2;for(const p of hands){g.strokeStyle='#d9ee99';for(const [a,b]of connections){g.beginPath();g.moveTo(p[a].x*c.width,p[a].y*c.height);g.lineTo(p[b].x*c.width,p[b].y*c.height);g.stroke();}for(const q of p){g.fillStyle='#eef9d4';g.beginPath();g.arc(q.x*c.width,q.y*c.height,3,0,Math.PI*2);g.fill();}}if(mouth&&face.length){g.strokeStyle='#d9ee99';g.beginPath();for(const [i,k]of [61,40,37,0,267,270,291,321,314,17,84,91,61].entries()){const p=face[k];i?g.lineTo(p.x*c.width,p.y*c.height):g.moveTo(p.x*c.width,p.y*c.height);}g.stroke();}}
async function frames(t){if(!running)return;if(!busy&&t-lastFrame>65&&$('video').readyState>=2){busy=true;lastFrame=t;const gen=generation;try{const bitmap=await createImageBitmap($('video'));if(!running||gen!==generation){bitmap.close();return;}worker.postMessage({type:'frame',bitmap,time:t},[bitmap]);}catch(e){fail(e);return;}}if(t-lastResult>450&&gate){gate=false;rightSeen=0;mouth=false;refresh();}raf=requestAnimationFrame(frames);}
function stopCamera(){generation++;clearTimeout(loadTimer);running=false;starting=false;cancelAnimationFrame(raf);worker?.terminate();worker=null;stream?.getTracks().forEach(t=>t.stop());stream=null;$('video').srcObject=null;gate=false;rightSeen=0;lastBowTime=0;brightness=.5;mouth=false;mutedUntilAbsent=false;thumbLocked=false;thumbDir=0;candidate=-1;busy=false;preview=false;$('overlay').getContext('2d').clearRect(0,0,$('overlay').width,$('overlay').height);$('start').disabled=false;$('start').textContent='◉ Start camera & sound';$('stop').hidden=true;$('welcome').hidden=false;$('zoneLabels').hidden=true;$('bowZones').hidden=true;$('live').textContent='● CAMERA OFF';['leftTrack','rightTrack','faceTrack'].forEach(x=>track(x,false));refresh();}
function fail(e){stopCamera();$('status').textContent=e.name==='NotAllowedError'?'Camera permission was denied. Allow it in your browser, or use Play the strings.':'Tracking could not start: '+e.message+'. You can still use Play the strings.';}
$('start').onclick=async()=>{if(starting||running)return;starting=true;const gen=++generation;preview=false;$('start').disabled=true;$('start').textContent='Loading instrument…';$('status').textContent='Loading gesture models. The first start may take a moment.';try{await synth.ready();if(gen!==generation)return;const incoming=await navigator.mediaDevices.getUserMedia({audio:false,video:{width:640,height:480,facingMode:'user'}});if(gen!==generation){incoming.getTracks().forEach(t=>t.stop());return;}stream=incoming;$('video').srcObject=stream;await $('video').play();if(gen!==generation)return;$('stop').hidden=false;worker=new Worker('./tracker.js');loadTimer=setTimeout(()=>{if(gen===generation)fail(new Error('Model loading timed out; check your internet connection'));},60000);worker.onmessage=({data})=>{if(gen!==generation)return;if(data.type==='ready'){clearTimeout(loadTimer);starting=false;running=true;busy=false;lastResult=performance.now();$('live').textContent='● LIVE';$('welcome').hidden=true;$('zoneLabels').hidden=false;$('bowZones').hidden=false;raf=requestAnimationFrame(frames);}else if(data.type==='result'){busy=false;process(data);}else fail(new Error(data.message));};worker.onerror=e=>fail(new Error(e.message||'Tracking worker failed'));worker.postMessage({type:'init'});}catch(e){if(gen===generation)fail(e);}};
$('stop').onclick=()=>{stopCamera();$('status').textContent='Camera stopped. Play the strings or start again.';};$('swap').onchange=()=>{rightSeen=0;gate=false;thumbLocked=false;thumbDir=0;refresh();};
window.addEventListener('keydown',e=>{if(e.key==='Escape'){silence();return;}if(e.target.matches('input,button,summary'))return;if(e.key===' '&&mode==='camera'){e.preventDefault();if(!e.repeat){preview=true;sound();}}});window.addEventListener('keyup',e=>{if(e.key===' ')releasePreview();});window.addEventListener('blur',()=>{if(preview)releasePreview();});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopCamera();silence();$('status').textContent='Sound and camera stopped while the page was hidden.';}});window.addEventListener('pagehide',()=>{stopCamera();silence();});drawStaff();render();
